using System; using System.Text.Json; using System.Threading; using System.Threading.Tasks; using Parcs.Agent.Runtime;
public class R { public double Value { get; set; } }
public class Part : IAgentComputation { public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input,CancellationToken ct) { double a=double.Parse(input.Parameters["a"],System.Globalization.CultureInfo.InvariantCulture), b=double.Parse(input.Parameters["b"],System.Globalization.CultureInfo.InvariantCulture); int n=10000; double h=(b-a)/n, sum=Math.Exp(-a/4.0)*Math.Cos(a+0.5*Math.Sin(2*a))+Math.Exp(-b/4.0)*Math.Cos(b+0.5*Math.Sin(2*b)); for(int i=1;i<n;i++){ double x=a+i*h; sum+=(i%2==0?2.0:4.0)*Math.Exp(-x/4.0)*Math.Cos(x+0.5*Math.Sin(2*x)); } return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new R { Value=sum*h/3.0 }))); } }
public class Reduce : IAgentComputation { public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input,CancellationToken ct) { double total=0; for(int j=0;j<2;j++){ string[] outputs=input.GetPreviousOutputs(j); foreach(string s in outputs) if(s!=null) total+=JsonSerializer.Deserialize<R>(s).Value; } return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new R { Value=total }))); } }
